-- Catálogo bilíngue 9/10, parte 1/4 (500 palavras). Execute as quatro partes em ordem.
-- Reexecutável: atualiza definition_pt e example_pt de palavras já importadas.
begin;
do $$ begin if exists (select 1 from (select unnest(array['arts', 'business', 'food', 'general-vocabulary', 'health', 'law', 'politics', 'science', 'sports', 'technical', 'technology']) as slug) required left join public.vocabulary_categories c using (slug) where c.id is null) then raise exception 'Categorias do catálogo ausentes'; end if; end $$;
insert into public.vocabulary_words (word,translation,definition_en,definition_pt,example_en,example_pt,cefr_level,word_type,category_id,frequency_rank)
select v.word,v.translation,v.definition_en,v.definition_pt,v.example_en,v.example_pt,v.cefr_level,v.word_type,c.id,v.frequency_rank
from jsonb_to_recordset($catalog$
[
{"word":"aperiodic","translation":"aperiódico","definition_en":"Describes events or phenomena that do not happen at fixed or predictable periods.","definition_pt":"Descreve eventos ou fenômenos que não acontecem em períodos fixos ou previsíveis.","example_en":"The machine produced an aperiodic signal that was difficult to analyze.","example_pt":"A máquina produziu um sinal aperiódico que era difícil de analisar.","cefr_level":"C1","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"apery","translation":"macaquice","definition_en":"The act of copying or mimicking someone else's behavior, speech, or actions.","definition_pt":"O ato de copiar ou imitar o comportamento, discurso ou ações de outra pessoa.","example_en":"His apery of the professor's mannerisms was quite amusing.","example_pt":"Sua apiedade dos modos do professor foi bem divertida.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apetalous","translation":"apétalo","definition_en":"Describes a flower that lacks petals, often relying on other structures for pollination.","definition_pt":"Descreve uma flor que não tem pétalas, muitas vezes confiando em outras estruturas para polinização.","example_en":"The apetalous flowers of the willow tree are wind-pollinated.","example_pt":"As flores apetalosas do salgueiro são polidas pelo vento.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"aphagia","translation":"afagia","definition_en":"The medical condition characterized by the loss or inability to swallow, often due to neurological or muscular disorders.","definition_pt":"A condição médica caracterizada pela perda ou incapacidade de engolir, muitas vezes devido a distúrbios neurológicos ou musculares.","example_en":"The patient was diagnosed with aphagia after the stroke.","example_pt":"O paciente foi diagnosticado com afagia após o derrame.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"aphakia","translation":"afaquia","definition_en":"A medical condition characterized by the absence of the natural crystalline lens of the eye, typically resulting from surgical removal due to cataracts or trauma.","definition_pt":"Uma condição médica caracterizada pela ausência do cristalino natural do olho, tipicamente resultante de remoção cirúrgica devido a catarata ou trauma.","example_en":"After cataract surgery, the patient was diagnosed with aphakia in the left eye.","example_pt":"Após a cirurgia de catarata, o paciente foi diagnosticado com afaquia no olho esquerdo.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"aphakic","translation":"afáquico","definition_en":"Of or relating to the condition of aphakia, where the eye's natural lens is absent.","definition_pt":"Ou relacionado com a condição de afakia, onde a lente natural do olho está ausente.","example_en":"Aphakic glasses are designed to compensate for the missing lens.","example_pt":"Óculos afáquicos são projetados para compensar a lente que falta.","cefr_level":"C2","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"aphanitic","translation":"afanítico","definition_en":"Describing the texture of an igneous rock in which the individual mineral crystals are too small to be seen with the naked eye.","definition_pt":"Descrevendo a textura de uma rocha ígnea em que os cristais minerais individuais são muito pequenos para serem vistos a olho nu.","example_en":"The sample had an aphanitic texture, indicating rapid cooling.","example_pt":"A amostra tinha uma textura afanítica, indicando rápido resfriamento.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"aphasic","translation":"afásico","definition_en":"Relating to or affected by aphasia, a condition that impairs the ability to understand or produce language due to brain damage.","definition_pt":"Relacionado ou afetado pela afasia, uma condição que prejudica a capacidade de entender ou produzir linguagem devido a danos cerebrais.","example_en":"The aphasic patient struggled to find the right words during therapy.","example_pt":"O paciente afásico lutou para encontrar as palavras certas durante a terapia.","cefr_level":"C1","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"aphelion","translation":"afélio","definition_en":"The point in the orbit of a planet, comet, or other celestial body that is farthest from the Sun.","definition_pt":"O ponto na órbita de um planeta, cometa ou outro corpo celestial que está mais distante do Sol.","example_en":"Earth reaches its aphelion in early July each year.","example_pt":"A Terra atinge seu afélio no início de julho de cada ano.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"apheresis","translation":"aférese","definition_en":"The loss of one or more sounds or letters from the beginning of a word, such as 'coon' from 'raccoon' or 'till' from 'until'.","definition_pt":"A perda de um ou mais sons ou letras do início de uma palavra, como 'cabo' de 'raccoon' ou 'até' de 'até'.","example_en":"'Phone' is a common apheresis of 'telephone'.","example_pt":"Telefone é uma aferese comum de telefone.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"aphesis","translation":"aférese","definition_en":"The gradual loss of an unstressed vowel or syllable at the beginning of a word, as seen in the evolution of 'squire' from 'esquire'.","definition_pt":"A perda gradual de uma vogal ou sílaba sem tensão no início de uma palavra, como visto na evolução do 'esquisito' do 'esquisito'.","example_en":"Linguists study aphesis to understand how languages change over time.","example_pt":"Linguistas estudam afese para entender como as línguas mudam com o tempo.","cefr_level":"C2","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"aphid","translation":"pulgão","definition_en":"A small insect that feeds on plant sap, often causing damage to crops and garden plants.","definition_pt":"Um pequeno inseto que se alimenta de seiva vegetal, causando muitas vezes danos às culturas e plantas de jardim.","example_en":"Aphids can quickly infest a rose bush if not controlled.","example_pt":"Os pulgões infestam rapidamente uma roseira se não for controlada.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"aphonia","translation":"afonia","definition_en":"A medical condition characterized by the inability to produce vocal sounds, often due to damage or dysfunction of the vocal cords or related nerves.","definition_pt":"Uma condição médica caracterizada pela incapacidade de produzir sons vocais, muitas vezes devido a danos ou disfunção das cordas vocais ou nervos relacionados.","example_en":"The singer was diagnosed with aphonia after straining her voice.","example_pt":"A cantora foi diagnosticada com afonia depois de forçar a voz.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"aphorism","translation":"aforismo","definition_en":"A concise statement of a general truth or principle, often witty or memorable.","definition_pt":"Uma declaração concisa de uma verdade ou princípio geral, muitas vezes espirituoso ou memorável.","example_en":"'Knowledge is power' is a well-known aphorism.","example_pt":"\"Conhecimento é poder\" é um aforismo bem conhecido.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"aphorist","translation":"aforista","definition_en":"A person who writes or frequently uses short, clever statements that express a general truth or observation.","definition_pt":"Uma pessoa que escreve ou usa declarações curtas e inteligentes que expressam uma verdade ou observação geral.","example_en":"The ancient Greek aphorist Hippocrates is known for his medical maxims.","example_pt":"O antigo aforista grego Hipócrates é conhecido por suas máximas médicas.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"aphoristic","translation":"aforístico","definition_en":"Characterized by the use of short, memorable sayings that express a general truth or piece of advice.","definition_pt":"Caracterizado pelo uso de pequenos e memoráveis ditados que expressam uma verdade geral ou um conselho.","example_en":"His writing style is highly aphoristic, filled with memorable quotes.","example_pt":"Seu estilo de escrita é altamente aforista, cheio de citações memoráveis.","cefr_level":"C1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"aphotic","translation":"afótico","definition_en":"Describing a zone or environment that receives no sunlight, especially in deep water.","definition_pt":"Descrevendo uma zona ou ambiente que não recebe luz solar, especialmente em águas profundas.","example_en":"The aphotic zone of the ocean begins at a depth of about 1,000 meters.","example_pt":"A zona afótica do oceano começa a uma profundidade de cerca de 1.000 metros.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"apiary","translation":"apiário","definition_en":"A structure or shed that houses a collection of beehives for keeping bees.","definition_pt":"Uma estrutura ou galpão que abriga uma coleção de colmeias para manter abelhas.","example_en":"The beekeeper built a new apiary in the backyard.","example_pt":"O apicultor construiu um novo apiário no quintal.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apical","translation":"apical","definition_en":"Located at the highest point, tip, or apex of something.","definition_pt":"Localizado no ponto mais alto, ponta ou ápice de algo.","example_en":"The apical bud is the main growing point of the plant.","example_pt":"O botão apical é o principal ponto de crescimento da planta.","cefr_level":"C1","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"apicultural","translation":"apícola","definition_en":"Pertaining to the practice of keeping and breeding bees, especially for honey production.","definition_pt":"Pertencia à prática de manter e reproduzir abelhas, especialmente para a produção de mel.","example_en":"The apicultural society held a workshop on hive management.","example_pt":"A sociedade apicultural realizou uma oficina sobre gestão de colmeias.","cefr_level":"C1","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"aplasia","translation":"aplasia","definition_en":"The failure of an organ or tissue to develop normally or at all, often present from birth.","definition_pt":"A falha de um órgão ou tecido para se desenvolver normalmente ou em tudo, muitas vezes presente desde o nascimento.","example_en":"Aplasia of the bone marrow leads to a lack of blood cell production.","example_pt":"Aplasia da medula óssea leva à falta de produção de células sanguíneas.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"apneic","translation":"apneico","definition_en":"Of or relating to a temporary cessation of breathing, especially during sleep.","definition_pt":"De ou se relacionar com uma cessação temporária da respiração, especialmente durante o sono.","example_en":"The patient was diagnosed with an apneic condition.","example_pt":"O paciente foi diagnosticado com uma condição apneica.","cefr_level":"C1","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"apochromatic","translation":"apocromático","definition_en":"Describes a lens or optical system that is designed to bring three wavelengths of light into focus at the same point, effectively correcting both chromatic and spherical aberration for superior image quality.","definition_pt":"Descreve uma lente ou sistema óptico que foi projetado para colocar três comprimentos de onda de luz em foco no mesmo ponto, corrigindo efetivamente a aberração cromática e esférica para uma qualidade de imagem superior.","example_en":"The telescope uses an apochromatic lens to produce sharp, color-free images.","example_pt":"O telescópio usa uma lente apocromática para produzir imagens nítidas e livres de cores.","cefr_level":"C2","word_type":"adjective","category_slug":"technical","frequency_rank":null},
{"word":"apocope","translation":"apócope","definition_en":"The linguistic process of shortening a word by removing one or more sounds or letters from its end.","definition_pt":"O processo linguístico de encurtar uma palavra removendo um ou mais sons ou letras de seu fim.","example_en":"In informal speech, 'info' is an apocope of 'information'.","example_pt":"Em discurso informal, 'info' é um apocope de 'informação'.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apocrine","translation":"apócrino","definition_en":"Relating to a type of exocrine gland where the secretion is produced by the release of part of the secreting cell's cytoplasm along with the secretory product.","definition_pt":"Relacionando-se a um tipo de glândula exócrina onde a secreção é produzida pela liberação de parte do citoplasma da célula secretadora junto com o produto secretor.","example_en":"Apocrine sweat glands are found in the armpits and groin area.","example_pt":"Glândulas apócrinas são encontradas nas axilas e na virilha.","cefr_level":"C2","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"apocryphal","translation":"apócrifo","definition_en":"Of doubtful authenticity, although widely circulated as being true.","definition_pt":"De autenticidade duvidosa, embora amplamente circulado como sendo verdade.","example_en":"The story about the CEO's childhood is likely apocryphal.","example_pt":"A história sobre a infância do diretor é provavelmente apócrifo.","cefr_level":"C1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apocynaceous","translation":"apocináceo","definition_en":"Of or relating to tropical plants of the family Apocynaceae, which includes many species with milky sap and often showy flowers.","definition_pt":"De ou relacionados com plantas tropicais da família Apocynaceae, que inclui muitas espécies com seiva leitosa e muitas vezes flores vistosas.","example_en":"The apocynaceous plants in the garden include oleander and periwinkle.","example_pt":"As plantas apocynaceous no jardim incluem oleander e periwinkle.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"apodeme","translation":"apodema","definition_en":"A ridge-like ingrowth of the exoskeleton of an arthropod that supports internal organs and provides attachment points for muscles.","definition_pt":"Um crescimento semelhante ao de um exoesqueleto de um artrópode que suporta órgãos internos e fornece pontos de fixação para músculos.","example_en":"The apodeme serves as an anchor for the insect's flight muscles.","example_pt":"O apodema serve de âncora para os músculos de vôo do inseto.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"apoenzyme","translation":"apoenzima","definition_en":"The protein part of an enzyme that requires a cofactor or coenzyme to become catalytically active.","definition_pt":"A parte proteica de uma enzima que requer um cofator ou coenzima para se tornar catalíticamente ativa.","example_en":"The apoenzyme alone cannot catalyze the reaction until it binds with its coenzyme.","example_pt":"A apoenzima sozinha não pode catalisar a reação até que ela se ligue com sua coenzima.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"apogamy","translation":"apogamia","definition_en":"The development of a sporophyte from a gametophyte without the fusion of gametes, a form of asexual reproduction observed in some ferns and other plants.","definition_pt":"O desenvolvimento de um esporófito de um gametófito sem a fusão de gametas, uma forma de reprodução assexuada observada em algumas samambaias e outras plantas.","example_en":"Apogamy allows certain ferns to reproduce without fertilization.","example_pt":"Apogamia permite que certas samambaias se reproduzam sem fertilização.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"apogee","translation":"apogeu","definition_en":"The most successful, powerful, or important point in the development of something; a final climactic stage.","definition_pt":"O ponto mais bem sucedido, poderoso ou importante no desenvolvimento de algo, uma fase culminante final.","example_en":"The Roman Empire reached its apogee under the rule of Trajan.","example_pt":"O Império Romano chegou ao seu apogeu sob o domínio de Trajan.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"apolitical","translation":"apolítico","definition_en":"Not interested in or involved in politics; having no political affiliation or opinion.","definition_pt":"Não se interessa ou se envolve com política, não tem afiliação política ou opinião.","example_en":"The organization remains apolitical to avoid controversy.","example_pt":"A organização continua apolítica para evitar controvérsias.","cefr_level":"B2","word_type":"adjective","category_slug":"politics","frequency_rank":null},
{"word":"apologetics","translation":"apologética","definition_en":"A branch of theology focused on the reasoned defense and justification of Christian beliefs and teachings.","definition_pt":"Um ramo da teologia focado na defesa fundamentada e justificação de crenças e ensinamentos cristãos.","example_en":"He studied apologetics to better explain his faith to skeptics.","example_pt":"Ele estudou apologética para explicar melhor sua fé aos céticos.","cefr_level":"C2","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"apologist","translation":"apologista","definition_en":"A person who argues in defense or justification of a policy, institution, or belief system.","definition_pt":"Uma pessoa que argumenta em defesa ou justificação de uma política, instituição, ou sistema de crenças.","example_en":"He is a well-known apologist for the government's economic policies.","example_pt":"Ele é um conhecido apologista para as políticas econômicas do governo.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apologue","translation":"apólogo","definition_en":"A short narrative, often featuring animals or inanimate objects, that conveys a moral lesson.","definition_pt":"Uma narrativa curta, que frequentemente apresenta animais ou objetos inanimados, que transmite uma lição moral.","example_en":"Aesop's fables are classic examples of an apologue.","example_pt":"As fábulas de Esopo são exemplos clássicos de um apólogo.","cefr_level":"C1","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"apomictic","translation":"apomítico","definition_en":"Describing a plant that reproduces through apomixis, a form of asexual reproduction that does not involve fertilization.","definition_pt":"Descrevendo uma planta que se reproduz através de apomixis, uma forma de reprodução assexuada que não envolve fertilização.","example_en":"Many dandelion species are apomictic, producing seeds without pollination.","example_pt":"Muitas espécies de dente-de-leão são apomicíticas, produzindo sementes sem polinização.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"apomixis","translation":"apomixia","definition_en":"A type of reproduction in plants that occurs without fertilization, resulting in seeds that are genetically identical to the parent plant.","definition_pt":"Um tipo de reprodução em plantas que ocorre sem fertilização, resultando em sementes geneticamente idênticas às plantas progenitoras.","example_en":"Dandelions often reproduce through apomixis, producing seeds without pollination.","example_pt":"Dente-de-leão se reproduzem através de apomixis, produzindo sementes sem polinização.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"apomorphine","translation":"apomorfina","definition_en":"A morphine derivative that is not as strong as morphine; used as an emetic and in small doses as a sedative.","definition_pt":"Um derivado de morfina que não é tão forte quanto morfina, usado como emético e em pequenas doses como sedativo.","example_en":"The doctor prescribed apomorphine to induce vomiting after the poisoning.","example_pt":"O médico prescreveu apomorfina para induzir vômito após o envenenamento.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"aponeurosis","translation":"aponeurose","definition_en":"A sheet-like fibrous membrane that connects muscles to bones or other muscles, resembling a flattened tendon.","definition_pt":"Uma membrana fibrosa que liga músculos a ossos ou outros músculos, lembrando um tendão achatado.","example_en":"The aponeurosis of the external oblique muscle is a key structure in the abdominal wall.","example_pt":"A aponeurose do músculo oblíquo externo é uma estrutura chave na parede abdominal.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"aponeurotic","translation":"aponeurótico","definition_en":"Pertaining to a sheet-like fibrous membrane that connects muscles to bones or other muscles.","definition_pt":"Pertencia a uma membrana fibrosa tipo folha que liga músculos a ossos ou outros músculos.","example_en":"The aponeurotic layer of the abdominal wall provides structural support.","example_pt":"A camada aponeurótica da parede abdominal fornece suporte estrutural.","cefr_level":"C2","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"apophatic","translation":"apofático","definition_en":"Relating to a theological approach that describes God by stating what God is not, rather than what God is.","definition_pt":"Relacionando-se a uma abordagem teológica que descreve Deus ao afirmar o que Deus não é, em vez de o que Deus é.","example_en":"Apophatic theology emphasizes the ineffability of the divine.","example_pt":"Teologia Apofática enfatiza a inefabilidade do divino.","cefr_level":"C2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apophatism","translation":"apofatismo","definition_en":"A theological approach that describes the divine by stating what it is not, rather than what it is, emphasizing the ineffable and transcendent nature of God.","definition_pt":"Uma abordagem teológica que descreve o divino ao afirmar o que não é, ao invés do que é, enfatizando a natureza inefável e transcendente de Deus.","example_en":"Apophatism is central to the mystical traditions of Eastern Christianity.","example_pt":"O apofatismo é central para as tradições místicas do cristianismo oriental.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"apophysis","translation":"apófise","definition_en":"A natural swelling or enlargement, such as at the base of the stalk or seta in certain mosses, or on the cone scale of certain conifers.","definition_pt":"Um inchaço natural ou aumento, como na base do talo ou seta em certos musgos, ou na escala de coníferas.","example_en":"The apophysis of the moss stalk helps in spore dispersal.","example_pt":"A apófise do talo de musgo ajuda na dispersão de esporos.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"apoplectic","translation":"apoplético","definition_en":"Pertaining to or characteristic of apoplexy, a sudden loss of consciousness due to a stroke or hemorrhage.","definition_pt":"Pertencia ou característica da apoplexia, uma perda súbita de consciência devido a um derrame ou hemorragia.","example_en":"The patient exhibited apoplectic symptoms after the stroke.","example_pt":"O paciente apresentou sintomas apopléticos após o derrame.","cefr_level":"C2","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"apoplexy","translation":"apoplexia","definition_en":"A sudden loss of consciousness, sensation, and voluntary motion caused by rupture or obstruction of a blood vessel in the brain.","definition_pt":"Uma perda súbita de consciência, sensação e movimento voluntário causado por ruptura ou obstrução de um vaso sanguíneo no cérebro.","example_en":"The patient was diagnosed with apoplexy after collapsing suddenly.","example_pt":"O paciente foi diagnosticado com apoplexia após colapso de repente.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"apoptosis","translation":"apoptose","definition_en":"A genetically controlled process of cell self-destruction that occurs in multicellular organisms, used to regulate cell numbers and remove damaged or unnecessary cells.","definition_pt":"Um processo geneticamente controlado de autodestruição celular que ocorre em organismos multicelulares, usado para regular o número de células e remover células danificadas ou desnecessárias.","example_en":"Apoptosis is essential for normal development, such as removing webbing between fingers in a human embryo.","example_pt":"Apoptose é essencial para o desenvolvimento normal, como remover a tecelagem entre os dedos em um embrião humano.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"aposiopesis","translation":"reticência","definition_en":"A sudden breaking off in the middle of a sentence, often to convey strong emotion or to leave something unsaid.","definition_pt":"Uma súbita ruptura no meio de uma frase, muitas vezes para transmitir emoções fortes ou deixar algo por dizer.","example_en":"The speaker used aposiopesis to emphasize his frustration: 'If you keep doing that, I'll...'","example_pt":"O orador usou aposiopesis para enfatizar sua frustração: \"Se continuar fazendo isso, eu... \"","cefr_level":"C2","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"apostasy","translation":"apostasia","definition_en":"The formal renunciation or abandonment of one's religious faith or principles.","definition_pt":"A renúncia formal ou abandono de sua fé ou princípios religiosos.","example_en":"His apostasy from the church shocked his family.","example_pt":"Sua apostasia da igreja chocou sua família.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apostate","translation":"apóstata","definition_en":"A person who renounces a religious belief or principle, often considered a traitor to their faith.","definition_pt":"Uma pessoa que renuncia a uma crença ou princípio religioso, muitas vezes considerado um traidor de sua fé.","example_en":"The apostate was excommunicated from the church.","example_pt":"O apóstata foi excomungado da igreja.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apostatize","translation":"apostatar","definition_en":"To formally abandon a religious belief, political party, or principle.","definition_pt":"Abandonar formalmente uma crença religiosa, partido político, ou princípio.","example_en":"He apostatized from the church after years of doubt.","example_pt":"Ele apostou na igreja depois de anos de dúvida.","cefr_level":"C2","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apostrophize","translation":"apostrofar","definition_en":"To insert or use an apostrophe in writing, typically to indicate possession or omission of letters.","definition_pt":"Para inserir ou usar um apóstrofo por escrito, tipicamente para indicar posse ou omissão de letras.","example_en":"The student learned how to apostrophize correctly in contractions.","example_pt":"O aluno aprendeu a apostrofizar corretamente em contrações.","cefr_level":"C1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apothecium","translation":"apotécio","definition_en":"A cup-shaped or saucer-shaped ascocarp that contains the spore-producing asci in many lichens and ascomycetous fungi.","definition_pt":"Um ascocarpo em forma de copo ou em forma de disco que contém as assi produtoras de esporos em muitos líquens e fungos ascomicetos.","example_en":"The lichen's apothecium was clearly visible under the microscope.","example_pt":"O apotécio do líquen estava claramente visível sob o microscópio.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"apothegm","translation":"apotegma","definition_en":"A brief, clever, and meaningful statement that expresses a general truth or piece of wisdom.","definition_pt":"Uma breve, inteligente e significativa declaração que expressa uma verdade geral ou um pedaço de sabedoria.","example_en":"The ancient philosopher was known for his many apothegms.","example_pt":"O filósofo antigo era conhecido por seus muitos apotegmas.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apotheosis","translation":"auge","definition_en":"The perfect example or highest form of something; a person or thing that is the ultimate embodiment of a quality.","definition_pt":"O exemplo perfeito ou a forma mais alta de algo, uma pessoa ou coisa que é a personificação final de uma qualidade.","example_en":"The painting is considered the apotheosis of Renaissance art.","example_pt":"A pintura é considerada a apoteose da arte renascentista.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apotropaic","translation":"apotropaico","definition_en":"Having the power or intended to prevent evil, harm, or bad luck.","definition_pt":"Ter o poder ou a intenção de evitar o mal, o mal ou a má sorte.","example_en":"Ancient cultures used apotropaic symbols to protect their homes.","example_pt":"Culturas antigas usavam símbolos apotrópicos para proteger suas casas.","cefr_level":"C2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"appall","translation":"consternar","definition_en":"To cause someone to feel great shock, horror, or dismay.","definition_pt":"Fazer alguém sentir grande choque, horror ou desânimo.","example_en":"The news of the accident appalled everyone in the community.","example_pt":"A notícia do acidente apavorou todos na comunidade.","cefr_level":"C1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apparatchik","translation":"apparatchik","definition_en":"A member of the administrative system of a communist party, especially in the former Soviet Union.","definition_pt":"Um membro do sistema administrativo de um partido comunista, especialmente na ex-União Soviética.","example_en":"The old apparatchik enforced party discipline without question.","example_pt":"O velho apparatchik impôs disciplina partidária sem dúvida.","cefr_level":"C2","word_type":"noun","category_slug":"politics","frequency_rank":null},
{"word":"appealable","translation":"apelável","definition_en":"Describes a legal decision or case that can be taken to a higher court for review.","definition_pt":"Descreve uma decisão legal ou caso que pode ser levado a um tribunal superior para revisão.","example_en":"The judge ruled that the verdict was appealable.","example_pt":"O juiz decidiu que o veredicto era apelativo.","cefr_level":"C1","word_type":"adjective","category_slug":"law","frequency_rank":null},
{"word":"appeaser","translation":"apaziguador","definition_en":"A person who attempts to maintain peace or avoid conflict by yielding to the demands of others, often at the expense of principles or long-term security.","definition_pt":"Uma pessoa que tenta manter a paz ou evitar conflitos cedendo às exigências dos outros, muitas vezes à custa de princípios ou segurança de longo prazo.","example_en":"History often judges an appeaser harshly for their concessions.","example_pt":"A história julga um apaziguador duramente por suas concessões.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"appellant","translation":"apelante","definition_en":"The person or party who makes an appeal to a higher court against a decision made by a lower court.","definition_pt":"A pessoa ou parte que faz um apelo a um tribunal superior contra uma decisão tomada por um tribunal inferior.","example_en":"The appellant argued that the trial judge had made a legal error.","example_pt":"O recorrente argumentou que o juiz do julgamento cometeu um erro legal.","cefr_level":"C1","word_type":"noun","category_slug":"law","frequency_rank":null},
{"word":"appellation","translation":"denominação","definition_en":"A name or title that identifies or describes someone or something.","definition_pt":"Um nome ou título que identifica ou descreve alguém ou algo assim.","example_en":"The appellation 'The Great' was given to the emperor.","example_pt":"A denominação \"O Grande\" foi dada ao imperador.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"appellative","translation":"apelativo","definition_en":"Serving to give a name or designate something.","definition_pt":"Servindo para dar um nome ou designar algo.","example_en":"The appellative function of language is crucial for identification.","example_pt":"A função apelativa da linguagem é crucial para identificação.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"append","translation":"anexar","definition_en":"To add something to the end of a document, text, or list.","definition_pt":"Para adicionar algo ao fim de um documento, texto ou lista.","example_en":"Please append your signature at the bottom of the page.","example_pt":"Por favor, acrescente sua assinatura no final da página.","cefr_level":"B2","word_type":"verb","category_slug":"technology","frequency_rank":null},
{"word":"apperception","translation":"apercepção","definition_en":"The mental process by which a person integrates new perceptions with their existing knowledge and past experiences.","definition_pt":"O processo mental pelo qual uma pessoa integra novas percepções com seus conhecimentos existentes e experiências passadas.","example_en":"Apperception allows a child to understand a new concept by connecting it to something they already know.","example_pt":"A percepção permite que uma criança entenda um novo conceito conectando-o a algo que já sabem.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"applauder","translation":"aplaudidor","definition_en":"A person who shows approval or praise by clapping their hands.","definition_pt":"Uma pessoa que mostra aprovação ou elogios batendo palmas.","example_en":"The applauders cheered loudly after the final act.","example_pt":"Os aplausos aplaudiram alto após o ato final.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"applet","translation":"applet","definition_en":"A small application program that runs within a larger program, typically a web browser, often written in Java.","definition_pt":"Um pequeno programa de aplicação que é executado dentro de um programa maior, tipicamente um navegador, muitas vezes escrito em Java.","example_en":"The website used a Java applet to display an interactive graph.","example_pt":"O site usou um applet Java para exibir um gráfico interativo.","cefr_level":"B2","word_type":"noun","category_slug":"technology","frequency_rank":null},
{"word":"applicability","translation":"aplicabilidade","definition_en":"The quality of being relevant, appropriate, or able to be applied to a particular situation or matter.","definition_pt":"A qualidade de ser relevante, apropriado ou capaz de ser aplicado a uma determinada situação ou matéria.","example_en":"The applicability of this law to digital transactions is still debated.","example_pt":"A aplicabilidade desta lei às transações digitais ainda é debatida.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"applicator","translation":"aplicador","definition_en":"A tool or instrument used to apply a substance, such as paint, glue, or medicine, to a surface.","definition_pt":"Uma ferramenta ou instrumento usado para aplicar uma substância, como tinta, cola, ou remédio, em uma superfície.","example_en":"She used a foam applicator to spread the glue evenly.","example_pt":"Ela usou um aplicador de espuma para espalhar a cola uniformemente.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"appoggiatura","translation":"apogiatura","definition_en":"An embellishing note, usually written in smaller size, that precedes a main note and is typically played on the beat, taking half or more of the main note's time value.","definition_pt":"Uma nota embelezadora, geralmente escrita em tamanho menor, que precede uma nota principal e é tipicamente tocada na batida, tomando metade ou mais do valor de tempo da nota principal.","example_en":"The pianist added a delicate appoggiatura to the melody.","example_pt":"O pianista adicionou uma delicada aploggiatura à melodia.","cefr_level":"C2","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"apportion","translation":"repartir","definition_en":"To divide and assign something among several people or groups.","definition_pt":"Dividir e atribuir algo entre várias pessoas ou grupos.","example_en":"The committee will apportion the funds among the various departments.","example_pt":"O comitê repartirá os fundos entre os vários departamentos.","cefr_level":"C1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apportionment","translation":"repartição","definition_en":"The act of distributing or allocating something, such as resources, funds, or seats, according to a plan or rule.","definition_pt":"O ato de distribuir ou alocar algo, como recursos, fundos, ou assentos, de acordo com um plano ou regra.","example_en":"The apportionment of seats in parliament is based on population.","example_pt":"A repartição de assentos no parlamento é baseada na população.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apposite","translation":"apropriado","definition_en":"Strikingly suitable and relevant to the situation or subject at hand.","definition_pt":"Muito adequado e relevante para a situação ou assunto em questão.","example_en":"Her comment was apposite to the discussion.","example_pt":"O comentário dela foi apropriado para a discussão.","cefr_level":"C1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apposition","translation":"aposição","definition_en":"A grammatical construction where two elements, usually noun phrases, are placed side by side, with one element serving to identify or describe the other.","definition_pt":"Uma construção gramatical onde dois elementos, geralmente frases substantivas, são colocados lado a lado, com um elemento servindo para identificar ou descrever o outro.","example_en":"In the phrase 'my friend John', 'John' is in apposition to 'my friend'.","example_pt":"Na frase 'meu amigo John', 'John' está em oposição a 'meu amigo'.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"appositive","translation":"apositivo","definition_en":"Describing a grammatical construction where a noun or noun phrase is placed next to another noun to rename or identify it.","definition_pt":"Descrevendo uma construção gramatical onde um substantivo ou frase é colocado ao lado de outro substantivo para renomeá-la ou identificá-la.","example_en":"In the phrase 'my brother, the doctor,' the word 'doctor' is an appositive noun.","example_pt":"Na frase 'meu irmão, o doutor', a palavra 'médico' é um substantivo positivo.","cefr_level":"C1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"appreciable","translation":"apreciável","definition_en":"Large or important enough to be noticed or measured.","definition_pt":"Grande ou importante o suficiente para ser notado ou medido.","example_en":"There has been an appreciable increase in sales this quarter.","example_pt":"Houve um aumento considerável nas vendas neste trimestre.","cefr_level":"B2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"appreciator","translation":"apreciador","definition_en":"Someone who fully understands and values the worth, quality, or significance of something.","definition_pt":"Alguém que entenda e valorize o valor, qualidade ou significado de algo.","example_en":"She is a true appreciator of classical music.","example_pt":"Ela é uma verdadeira apreciadora da música clássica.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apprehender","translation":"apreendedor","definition_en":"An individual who grasps or comprehends something mentally.","definition_pt":"Um indivíduo que entende ou compreende algo mentalmente.","example_en":"He was a quick apprehender of complex theories.","example_pt":"Ele foi um rápido apreendedor de teorias complexas.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apprehensively","translation":"apreensivamente","definition_en":"In a manner that shows fear or unease about something that might happen.","definition_pt":"De uma forma que mostra medo ou desconforto sobre algo que pode acontecer.","example_en":"She looked around apprehensively before entering the dark room.","example_pt":"Ela olhou apreensivamente antes de entrar na sala escura.","cefr_level":"B2","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apprehensiveness","translation":"apreensividade","definition_en":"A feeling of fear or unease about something that might happen.","definition_pt":"Um sentimento de medo ou desconforto sobre algo que pode acontecer.","example_en":"She felt a sense of apprehensiveness before the job interview.","example_pt":"Ela sentiu uma sensação de apreensão antes da entrevista de emprego.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apprise","translation":"avisar","definition_en":"To give someone information about something; to notify or make aware.","definition_pt":"Para dar informações a alguém sobre algo, para avisar ou para dar atenção.","example_en":"Please apprise me of any changes to the schedule.","example_pt":"Por favor, me informe sobre qualquer mudança na agenda.","cefr_level":"B2","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"appropriator","translation":"apropriador","definition_en":"A person who takes something, especially without permission, for their own use.","definition_pt":"Uma pessoa que toma algo, especialmente sem permissão, para seu próprio uso.","example_en":"The appropriator of the funds was caught by the auditors.","example_pt":"O proprietário dos fundos foi pego pelos auditores.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"approver","translation":"aprovador","definition_en":"A person or entity that has the authority to officially agree to or sanction something.","definition_pt":"Uma pessoa ou entidade que tem a autoridade para concordar oficialmente ou sancionar algo.","example_en":"The project cannot proceed without the signature of the approver.","example_pt":"O projeto não pode prosseguir sem a assinatura do aprovador.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"appurtenance","translation":"apetrechos","definition_en":"Items or tools that are necessary or useful for a particular activity, operation, or sport.","definition_pt":"Itens ou ferramentas que são necessários ou úteis para uma atividade, operação ou esporte.","example_en":"The kitchen was filled with all the necessary appurtenances for gourmet cooking.","example_pt":"A cozinha estava cheia de todas as coisas necessárias para cozinhar gourmet.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apraxia","translation":"apraxia","definition_en":"A neurological condition characterized by the inability to perform purposeful, learned movements despite having the physical ability and desire to do so.","definition_pt":"Uma condição neurológica caracterizada pela incapacidade de realizar movimentos propositalmente aprendidos apesar de ter a habilidade física e desejo de fazê-lo.","example_en":"The patient was diagnosed with apraxia after struggling to wave goodbye.","example_pt":"O paciente foi diagnosticado com apraxia depois de lutar para se despedir.","cefr_level":"C2","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"apraxic","translation":"apráxico","definition_en":"Relating to or characterized by an inability to perform purposeful movements, despite having the desire and physical ability to do so, often due to a neurological condition.","definition_pt":"Relacionado ou caracterizado por uma incapacidade de realizar movimentos propositais, apesar de ter o desejo e capacidade física para fazê-lo, muitas vezes devido a uma condição neurológica.","example_en":"The patient was diagnosed as apraxic after the stroke.","example_pt":"O paciente foi diagnosticado como apráxico após o derrame.","cefr_level":"C2","word_type":"adjective","category_slug":"health","frequency_rank":null},
{"word":"apse","translation":"ábside","definition_en":"A semicircular or polygonal recess, often with a domed or vaulted roof, typically found at the eastern end of a church and housing the altar.","definition_pt":"Um recesso semicircular ou poligonal, muitas vezes com um teto abobadado ou com cúpula, normalmente encontrado no extremo leste de uma igreja e abrigando o altar.","example_en":"The priest stood in the apse before the congregation.","example_pt":"O padre estava na abside diante da congregação.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"apsis","translation":"apside","definition_en":"A curved or domed recess, often at the eastern end of a church, typically housing the altar.","definition_pt":"Um recesso curvo ou abobadado, muitas vezes no extremo leste de uma igreja, tipicamente abrigando o altar.","example_en":"The ancient church had a beautifully decorated apsis.","example_pt":"A antiga igreja tinha uma bela apsis decorada.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"aptness","translation":"aptidão","definition_en":"A natural inclination or tendency to behave in a particular manner.","definition_pt":"Uma inclinação natural ou tendência a se comportar de uma maneira particular.","example_en":"His aptness for quick decision-making made him a great leader.","example_pt":"Sua capacidade de tomar decisões rápidas o tornou um grande líder.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"aquacultural","translation":"aquícola","definition_en":"Pertaining to the cultivation of aquatic organisms such as fish, shellfish, and plants in controlled water environments.","definition_pt":"Pertencia ao cultivo de organismos aquáticos, como peixes, mariscos e plantas em ambientes aquáticos controlados.","example_en":"The aquacultural industry has grown significantly in coastal regions.","example_pt":"A indústria aquacultural cresceu significativamente nas regiões costeiras.","cefr_level":"C1","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"aquaculture","translation":"aquicultura","definition_en":"The controlled cultivation and harvesting of fish, shellfish, algae, and other aquatic organisms in water environments for food or other products.","definition_pt":"O cultivo controlado e colheita de peixes, mariscos, algas e outros organismos aquáticos em ambientes aquáticos para alimentos ou outros produtos.","example_en":"Aquaculture provides a sustainable source of seafood to meet global demand.","example_pt":"A aquicultura fornece uma fonte sustentável de frutos do mar para atender à demanda global.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"aquamarine","translation":"água-marinha","definition_en":"A transparent, pale blue-green variety of the mineral beryl, often used as a gemstone in jewelry.","definition_pt":"Uma transparente, pálida variedade azul-verde da berilo mineral, muitas vezes usado como uma pedra preciosa em jóias.","example_en":"She wore a beautiful aquamarine pendant around her neck.","example_pt":"Ela usava um lindo pingente de água-marinho no pescoço.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"aquanaut","translation":"aquanauta","definition_en":"A person who swims underwater using equipment such as a face mask, fins, and a snorkel or air cylinder.","definition_pt":"Uma pessoa que nada debaixo d'água usando equipamento como máscara facial, barbatanas, e um snorkel ou cilindro de ar.","example_en":"The aquanaut descended to the coral reef to study marine life.","example_pt":"O aquanaut desceu ao recife de coral para estudar a vida marinha.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"aquaphobia","translation":"aquafobia","definition_en":"An abnormal and persistent fear of water, including drowning, swimming, or even being near large bodies of water.","definition_pt":"Um medo anormal e persistente da água, incluindo afogamento, natação, ou mesmo estar perto de grandes corpos de água.","example_en":"Her aquaphobia prevented her from ever learning to swim.","example_pt":"A aquafobia dela a impediu de aprender a nadar.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"aquaplane","translation":"aquaplanar","definition_en":"To ride on a board that is towed behind a fast motorboat, skimming across the water's surface.","definition_pt":"Para andar em uma prancha que é rebocada atrás de uma lancha rápida, esgueirando-se através da superfície da água.","example_en":"They spent the afternoon aquaplaning behind the speedboat.","example_pt":"Passaram a tarde aquaplanando atrás da lancha.","cefr_level":"B2","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"aquaplaning","translation":"aquaplanagem","definition_en":"A dangerous driving condition where a layer of water builds between the tires of a vehicle and the road surface, causing the driver to lose control.","definition_pt":"Uma perigosa condição de condução onde uma camada de água se constrói entre os pneus de um veículo e a superfície da estrada, fazendo com que o motorista perca o controle.","example_en":"Aquaplaning can occur when driving too fast through deep puddles.","example_pt":"Aquaplaning pode ocorrer quando dirigindo muito rápido através de poças profundas.","cefr_level":"B2","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"aquatics","translation":"aquáticos","definition_en":"Sports or recreational activities that take place in or on water.","definition_pt":"Esportes ou atividades recreativas que acontecem dentro ou na água.","example_en":"The Olympics feature many aquatics, including swimming and diving.","example_pt":"As Olimpíadas apresentam muitos aquáticos, incluindo nadar e mergulhar.","cefr_level":"B1","word_type":"noun","category_slug":"sports","frequency_rank":null},
{"word":"aquatint","translation":"aquatinta","definition_en":"A method of etching that creates tonal effects similar to watercolor washes, using a resin ground to produce areas of varying darkness.","definition_pt":"Um método de gravação que cria efeitos tonais semelhantes aos lavadores de aquarela, usando um solo de resina para produzir áreas de escuridão variável.","example_en":"The artist used aquatint to achieve soft gradients in the landscape print.","example_pt":"O artista usou um aquaint para alcançar gradientes suaves na impressão da paisagem.","cefr_level":"C1","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"aquavit","translation":"aquavit","definition_en":"A strong, clear Scandinavian spirit typically flavored with caraway seeds and sometimes other herbs or spices.","definition_pt":"Um espírito escandinavo forte e claro tipicamente com sementes de alcaravia e às vezes outras ervas ou especiarias.","example_en":"They served chilled aquavit with the traditional smorgasbord.","example_pt":"Serviram aquavit gelado com o tradicional smorgasbord.","cefr_level":"B2","word_type":"noun","category_slug":"food","frequency_rank":null},
{"word":"aqueous","translation":"aquoso","definition_en":"Relating to, similar to, or containing water; dissolved in water.","definition_pt":"Relacionado com, similar ou contendo água, dissolvido em água.","example_en":"The aqueous solution was clear and odorless.","example_pt":"A solução aquosa era clara e inodora.","cefr_level":"C1","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"aquifer","translation":"aquífero","definition_en":"A body of permeable rock or sediment that can contain or transmit groundwater, often used as a source for wells and springs.","definition_pt":"Um corpo de rocha permeável ou sedimento que pode conter ou transmitir água subterrânea, muitas vezes usado como fonte para poços e fontes.","example_en":"The city relies on a large aquifer for its drinking water.","example_pt":"A cidade depende de um grande aquífero para sua água potável.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"aquiline","translation":"aquilino","definition_en":"Describing a nose that is curved or hooked, resembling the beak of an eagle.","definition_pt":"Descrevendo um nariz curvado ou preso, lembrando o bico de uma águia.","example_en":"He had a prominent aquiline nose that gave his face a distinguished look.","example_pt":"Ele tinha um nariz aquilino proeminente que lhe dava um olhar distinto.","cefr_level":"C1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"arabesque","translation":"arabesco","definition_en":"A ballet posture where the dancer stands on one leg while the other leg is extended straight back, often with one or both arms held in a graceful, flowing position.","definition_pt":"Uma postura de balé onde a dançarina fica em uma perna enquanto a outra perna é estendida para trás, muitas vezes com um ou ambos os braços mantidos em uma posição graciosa, fluindo.","example_en":"The ballerina held a perfect arabesque for several seconds.","example_pt":"A bailarina manteve um arabesco perfeito por vários segundos.","cefr_level":"B2","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"arability","translation":"arabilidade","definition_en":"The quality of land being suitable for plowing and growing crops.","definition_pt":"A qualidade da terra é adequada para arar e cultivar plantações.","example_en":"The arability of the region's soil made it ideal for wheat farming.","example_pt":"A arabilidade do solo da região o tornou ideal para a agricultura de trigo.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"arable","translation":"arável","definition_en":"Describes land that is capable of being plowed and used to grow crops.","definition_pt":"Descreve terras que são capazes de serem arados e usadas para cultivar.","example_en":"The region has vast areas of arable land.","example_pt":"A região tem vastas áreas de terra arável.","cefr_level":"B2","word_type":"adjective","category_slug":"technical","frequency_rank":null},
{"word":"arachnid","translation":"aracnídeo","definition_en":"An air-breathing arthropod characterized by simple eyes and four pairs of legs, belonging to the class Arachnida.","definition_pt":"Um artrópode que respira ar, caracterizado por olhos simples e quatro pares de pernas, pertencente à classe Aracnida.","example_en":"Spiders and scorpions are well-known examples of arachnids.","example_pt":"Aranhas e escorpiões são exemplos bem conhecidos de aracnídeos.","cefr_level":"B2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"arachnophobia","translation":"aracnofobia","definition_en":"An extreme or irrational fear of spiders and other arachnids.","definition_pt":"Um medo extremo ou irracional de aranhas e outros aracnídeos.","example_en":"Her arachnophobia makes it impossible for her to enter the basement.","example_pt":"A arachnofobia dela torna impossível para ela entrar no porão.","cefr_level":"C1","word_type":"noun","category_slug":"health","frequency_rank":null},
{"word":"aragonite","translation":"aragonita","definition_en":"A mineral composed of calcium carbonate (CaCO3), with a crystal structure different from calcite; often found in shells and pearls.","definition_pt":"Um mineral composto de carbonato de cálcio (CaCO3), com uma estrutura cristalina diferente da calcita, muitas vezes encontrada em conchas e pérolas.","example_en":"Aragonite is commonly found in the shells of marine mollusks.","example_pt":"Aragonite é comumente encontrada nas conchas de moluscos marinhos.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"arak","translation":"arak","definition_en":"A strong alcoholic spirit distilled from fermented sap of toddy palms or from fermented molasses, popular in the Middle East and South Asia.","definition_pt":"Um forte espírito alcoólico destilado de seiva fermentada de palmeiras ou de melaço fermentado, popular no Oriente Médio e no Sul da Ásia.","example_en":"He ordered a glass of arak with ice and water.","example_pt":"Ele pediu um copo de arak com gelo e água.","cefr_level":"B2","word_type":"noun","category_slug":"food","frequency_rank":null},
{"word":"aralia","translation":"arália","definition_en":"Any of various plants of the genus Aralia, often aromatic plants having compound leaves and small umbellate flowers.","definition_pt":"Qualquer uma das várias plantas do gênero Arália, muitas vezes plantas aromáticas com folhas compostas e pequenas flores de umbellate.","example_en":"The aralia in the garden has grown quite tall this year.","example_pt":"A arália no jardim cresceu bastante este ano.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"aramean","translation":"arameu","definition_en":"Of or pertaining to the ancient Semitic people who lived in Aram and parts of Mesopotamia from the 11th to the 8th century BC.","definition_pt":"Ou pertencente ao antigo povo semítico que viveu em Aram e partes da Mesopotâmia do século XI ao século VIII a.C.","example_en":"The Aramean culture had a significant influence on the region.","example_pt":"A cultura de Aramea teve uma influência significativa na região.","cefr_level":"C2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"arariba","translation":"araribá","definition_en":"A Brazilian tree known for its attractively patterned wood, often used in furniture and decorative items.","definition_pt":"Uma árvore brasileira conhecida por sua madeira de estampas atraentes, muitas vezes usada em móveis e objetos decorativos.","example_en":"The arariba tree is prized for its beautifully marked timber.","example_pt":"A árvore arariba é valorizada por sua madeira lindamente marcada.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"araucaria","translation":"araucária","definition_en":"A tall evergreen tree from the genus Araucaria, native to South America and Australia, known for its symmetrical shape, sharp needles, and large cones with edible seeds.","definition_pt":"Uma árvore evergreen alta do gênero Araucaria, nativa da América do Sul e Austrália, conhecida por sua forma simétrica, agulhas afiadas, e cones grandes com sementes comestíveis.","example_en":"The araucaria tree in the botanical garden is over a hundred years old.","example_pt":"A araucária no jardim botânico tem mais de cem anos.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"arbitrable","translation":"arbitrável","definition_en":"Appropriate for or capable of being settled by arbitration, a legal process where a neutral third party resolves a dispute.","definition_pt":"Apropriado para ou capaz de ser resolvido por arbitragem, um processo legal onde um terceiro neutro resolve uma disputa.","example_en":"The contract states that all disputes are arbitrable.","example_pt":"O contrato diz que todas as disputas são arbitrais.","cefr_level":"C1","word_type":"adjective","category_slug":"law","frequency_rank":null},
{"word":"arbitrage","translation":"arbitragem","definition_en":"A financial strategy that involves simultaneously buying and selling an asset in different markets to profit from temporary price differences.","definition_pt":"Uma estratégia financeira que envolve simultaneamente comprar e vender um ativo em diferentes mercados para lucrar com diferenças temporárias de preços.","example_en":"The trader used arbitrage to profit from the price gap between the New York and London stock exchanges.","example_pt":"O comerciante usou arbitragem para lucrar com a diferença de preços entre as bolsas de valores de Nova York e Londres.","cefr_level":"C1","word_type":"noun","category_slug":"business","frequency_rank":null},
{"word":"arbitral","translation":"arbitral","definition_en":"Pertaining to the process of settling a dispute by an impartial third party, or resulting from such a process.","definition_pt":"Pertendo o processo de resolver uma disputa por um terceiro imparcial, ou resultante de tal processo.","example_en":"The arbitral tribunal issued its final decision yesterday.","example_pt":"O tribunal arbitral emitiu sua decisão final ontem.","cefr_level":"C1","word_type":"adjective","category_slug":"law","frequency_rank":null},
{"word":"arbitrariness","translation":"arbitrariedade","definition_en":"The quality of acting based on whim or personal preference rather than logic or rules.","definition_pt":"A qualidade de agir baseado em capricho ou preferência pessoal, ao invés de lógica ou regras.","example_en":"The arbitrariness of the judge's decisions frustrated the lawyers.","example_pt":"A arbitrariedade das decisões do juiz frustrava os advogados.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"arbitrate","translation":"arbitrar","definition_en":"To act as an impartial third party to settle a disagreement between two or more parties.","definition_pt":"Para agir como um terceiro imparcial para resolver um desacordo entre duas ou mais partes.","example_en":"The judge was called to arbitrate the contract dispute.","example_pt":"O juiz foi chamado para arbitrar a disputa do contrato.","cefr_level":"C1","word_type":"verb","category_slug":"law","frequency_rank":null},
{"word":"arbitrator","translation":"árbitro","definition_en":"A person chosen to settle a disagreement or conflict between parties, often in a legal or formal setting.","definition_pt":"Uma pessoa escolhida para resolver um desentendimento ou conflito entre as partes, muitas vezes em um ambiente legal ou formal.","example_en":"The arbitrator listened to both sides before making a decision.","example_pt":"O árbitro ouviu os dois lados antes de tomar uma decisão.","cefr_level":"B2","word_type":"noun","category_slug":"law","frequency_rank":null},
{"word":"arboreal","translation":"arbóreo","definition_en":"Connected with, formed by, or characteristic of trees.","definition_pt":"Ligado com, formado por, ou característica de árvores.","example_en":"The arboreal canopy provides shelter for many birds.","example_pt":"O copa arbórea fornece abrigo para muitas aves.","cefr_level":"C1","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"arboretum","translation":"arboreto","definition_en":"A botanical garden or facility where trees, shrubs, and woody plants are grown for scientific study, conservation, and public display.","definition_pt":"Um jardim botânico ou uma instalação onde árvores, arbustos e plantas lenhosas são cultivadas para estudos científicos, conservação e exibição pública.","example_en":"The city's arboretum features over 500 species of trees from around the world.","example_pt":"O arboreto da cidade apresenta mais de 500 espécies de árvores de todo o mundo.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"arboriculture","translation":"arboricultura","definition_en":"The practice of growing and managing trees specifically for the production of wood and timber.","definition_pt":"A prática de cultivar e gerenciar árvores especificamente para a produção de madeira e madeira.","example_en":"Arboriculture is essential for sustainable timber production.","example_pt":"A arboricultura é essencial para a produção sustentável de madeira.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"arboriculturist","translation":"arboricultor","definition_en":"A professional who studies, cultivates, and manages trees, shrubs, and other woody plants, often in urban or forested environments.","definition_pt":"Um profissional que estuda, cultiva e gerencia árvores, arbustos e outras plantas lenhosas, muitas vezes em ambientes urbanos ou florestais.","example_en":"The arboriculturist assessed the health of the old oak tree in the park.","example_pt":"O arboriculturista avaliou a saúde do velho carvalho no parque.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"arborist","translation":"arborista","definition_en":"A professional who specializes in the cultivation, management, and treatment of trees, including diagnosing and treating damaged or diseased trees.","definition_pt":"Um profissional especializado em cultivo, manejo e tratamento de árvores, incluindo o diagnóstico e tratamento de árvores danificadas ou doentes.","example_en":"The arborist assessed the storm-damaged oak tree in the backyard.","example_pt":"O arborista avaliou o carvalho danificado pela tempestade no quintal.","cefr_level":"B2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"arbovirus","translation":"arbovírus","definition_en":"A large and diverse group of RNA viruses that are transmitted between vertebrate hosts by blood-feeding arthropods such as mosquitoes, ticks, sandflies, and midges. These viruses can cause a range of illnesses in humans, from mild fevers to severe conditions like encephalitis and hemorrhagic fever.","definition_pt":"Um grande e diversificado grupo de vírus RNA que são transmitidos entre hospedeiros vertebrados por artrópodes que se alimentam do sangue, como mosquitos, carrapatos, flebotomíneos e insetos. Estes vírus podem causar uma série de doenças em humanos, desde febres leves a condições graves como encefalite e febre hemorrágica.","example_en":"The arbovirus was isolated from a mosquito sample collected in the wetland area.","example_pt":"O arbovírus foi isolado de uma amostra de mosquito coletada na área úmida.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"arcadian","translation":"arcádio","definition_en":"A person who lives a simple, rustic life, often idealized as peaceful and harmonious with nature.","definition_pt":"Uma pessoa que vive uma vida simples e rústica, muitas vezes idealizada como pacífica e harmoniosa com a natureza.","example_en":"The poet portrayed himself as an arcadian, far from the corruption of the city.","example_pt":"O poeta se retratou como um arcadiano, longe da corrupção da cidade.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"arcanum","translation":"arcano","definition_en":"Information or knowledge that is known only to a select few; a deep secret or mystery.","definition_pt":"Informação ou conhecimento que é conhecido apenas por alguns, um segredo ou mistério profundo.","example_en":"Only the high priest knew the arcanum of the temple.","example_pt":"Apenas o sumo sacerdote conhecia o arcano do templo.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"arccosecant","translation":"arco-cossecante","definition_en":"The angle whose cosecant is equal to a given number; the inverse of the cosecant function.","definition_pt":"O ângulo cujo cossecante é igual a um determinado número, o inverso da função cosecante.","example_en":"The arccosecant of 2 is approximately 30 degrees.","example_pt":"O arcossecante de 2 é aproximadamente 30 graus.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"arccosine","translation":"arco cosseno","definition_en":"The inverse function of the cosine; the angle whose cosine equals a given number.","definition_pt":"A função inversa do cosseno, o ângulo cujo cosseno é igual a um determinado número.","example_en":"The arccosine of 0.5 is 60 degrees.","example_pt":"A arcosina de 0,5 é de 60 graus.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"archaean","translation":"arqueano","definition_en":"Of or relating to the Archaean Eon, the earliest part of the Precambrian, spanning from about 4.0 to 2.5 billion years ago, characterized by the formation of the Earth's first solid crust and the emergence of primitive life.","definition_pt":"De ou se relacionando com o Eon Archaean, a parte mais antiga do Precambrian, que se estende de cerca de 4,0 a 2,5 bilhões de anos atrás, caracterizada pela formação da primeira crosta sólida da Terra e o surgimento da vida primitiva.","example_en":"The Archaean rocks in this region are among the oldest on Earth.","example_pt":"As rochas arqueanas nesta região estão entre as mais antigas da Terra.","cefr_level":"C2","word_type":"adjective","category_slug":"science","frequency_rank":null},
{"word":"archaeozoic","translation":"Arqueozoico","definition_en":"The earliest eon of Earth's history, spanning from about 4 billion to 2.5 billion years ago, characterized by the formation of the Earth's crust and the emergence of the first simple life forms.","definition_pt":"O primeiro éon da história da Terra, que se estende de cerca de 4 bilhões a 2,5 bilhões de anos atrás, caracterizado pela formação da crosta da Terra e o surgimento das primeiras formas de vida simples.","example_en":"The Archaeozoic eon is also known as the Archean eon.","example_pt":"O éon Arqueozóico também é conhecido como éon Arqueano.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"archaist","translation":"arcaísta","definition_en":"A person who deliberately uses or imitates archaic words, expressions, or styles in speech or writing.","definition_pt":"Uma pessoa que deliberadamente usa ou imita palavras arcaicas, expressões, ou estilos em linguagem ou escrita.","example_en":"The author, a known archaist, filled his novel with 'thee' and 'thou'.","example_pt":"O autor, um conhecido archaist, encheu seu romance com 'thee' e 'thou'.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"archbishopric","translation":"arcebispado","definition_en":"The district, area, or region over which an archbishop has authority.","definition_pt":"O distrito, área ou região sobre o qual um arcebispo tem autoridade.","example_en":"The archbishopric of Canterbury is one of the most important in England.","example_pt":"O arcebispo de Canterbury é um dos mais importantes da Inglaterra.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"archdiocesan","translation":"arquidiocesano","definition_en":"Pertaining to an archdiocese, which is a large diocese governed by an archbishop.","definition_pt":"Pertencia a uma arquidiocese, que é uma grande diocese governada por um arcebispo.","example_en":"The archdiocesan council met to discuss the new policies.","example_pt":"O conselho arquidiocesano reuniu-se para discutir as novas políticas.","cefr_level":"C2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"archduchess","translation":"arquiduquesa","definition_en":"A wife or widow of an archduke, or a princess of the former ruling house of Austria.","definition_pt":"Uma esposa ou viúva de um arquiduque, ou uma princesa da antiga casa governante da Áustria.","example_en":"The archduchess attended the royal ball in Vienna.","example_pt":"A arquiduquesa assistiu ao baile real em Viena.","cefr_level":"C1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"archduchy","translation":"arquiducado","definition_en":"The territory, domain, or principality ruled by an archduke or archduchess.","definition_pt":"O território, domínio ou principado governado por um arquiduque ou arquiduquesa.","example_en":"The Archduchy of Austria was a major state within the Holy Roman Empire.","example_pt":"A Arquiduquia da Áustria era um estado importante dentro do Sacro Império Romano.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"archegonium","translation":"arquegônio","definition_en":"A multicellular, flask-shaped female sex organ found in bryophytes, ferns, and most gymnosperms, which produces and contains the egg cell.","definition_pt":"Um órgão feminino multicelular, em forma de frasco, encontrado em briófitas, samambaias e a maioria dos gymnosperms, que produz e contém o óvulo.","example_en":"The archegonium protects the developing egg cell in mosses.","example_pt":"O arquigônio protege o desenvolvimento de células de ovos em musgos.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"archenteron","translation":"arquêntero","definition_en":"The primitive gut that forms during the gastrulation stage of embryonic development, which eventually develops into the digestive tract.","definition_pt":"O intestino primitivo que se forma durante o estágio de gastrulação do desenvolvimento embrionário, que eventualmente se desenvolve no trato digestivo.","example_en":"The archenteron is a key structure in the early development of many animals.","example_pt":"O arquienteron é uma estrutura chave no desenvolvimento precoce de muitos animais.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"archeopteryx","translation":"arqueoptérix","definition_en":"An extinct primitive toothed bird from the Jurassic period, characterized by a long feathered tail and hollow bones, often considered the most primitive of all birds.","definition_pt":"Uma ave primitiva extinta do período Jurássico, caracterizada por uma cauda longa e emplumada e ossos ocos, muitas vezes considerados os mais primitivos de todos os pássaros.","example_en":"The archeopteryx is a key fossil in understanding the evolution of birds.","example_pt":"O arqueopteryx é um fóssil chave para entender a evolução das aves.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"archepiscopal","translation":"arquiepiscopal","definition_en":"Of or associated with an archbishop, the highest-ranking bishop in a province or diocese.","definition_pt":"De um arcebispo, o bispo de maior patente de uma província ou diocese.","example_en":"The archepiscopal palace was built in the 17th century.","example_pt":"O palácio arquepiscopal foi construído no século 17.","cefr_level":"C2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"archerfish","translation":"peixe-arqueiro","definition_en":"Any of several small freshwater fishes that catch insects by squirting water at them, knocking them into the water; found in Indonesia and Australia.","definition_pt":"Qualquer um dos peixes pequenos de água doce que pega insetos esguichando água neles, derrubando-os na água, encontrados na Indonésia e Austrália.","example_en":"The archerfish is known for its ability to shoot down insects with a precise stream of water.","example_pt":"O arqueiro é conhecido por sua capacidade de abater insetos com um fluxo preciso de água.","cefr_level":"C1","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"archetypal","translation":"arquetípico","definition_en":"Representing the most typical or perfect example of a particular kind of person or thing; serving as an original model after which others are patterned.","definition_pt":"Representando o exemplo mais típico ou perfeito de um tipo particular de pessoa ou coisa, servindo como um modelo original, após o qual outros são modelados.","example_en":"The hero's journey is an archetypal story structure found in many cultures.","example_pt":"A jornada do herói é uma estrutura arquetípica de histórias encontrada em muitas culturas.","cefr_level":"C2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"archiannelid","translation":"arquianelídeo","definition_en":"A small, primitive marine worm that lacks external segmentation and resembles the larvae of polychaete worms.","definition_pt":"Um pequeno verme marinho primitivo que não tem segmentação externa e se assemelha às larvas de vermes poliquetas.","example_en":"The archiannelid was discovered in the deep ocean sediment.","example_pt":"O arquiannelide foi descoberto no sedimento do oceano profundo.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"archiepiscopal","translation":"arcebispal","definition_en":"Pertaining to or associated with an archbishop, the highest-ranking bishop in a province or diocese.","definition_pt":"Pertencia ou estava associado a um arcebispo, o bispo de maior patente de uma província ou diocese.","example_en":"The archiepiscopal palace was built in the 16th century.","example_pt":"O palácio arquiepiscopal foi construído no século 16.","cefr_level":"C2","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"archimandrite","translation":"arquimandrita","definition_en":"A senior priest in certain Eastern Christian traditions who is the head of a monastery or a group of monasteries.","definition_pt":"Um padre sênior em certas tradições cristãs orientais que é o chefe de um mosteiro ou um grupo de mosteiros.","example_en":"The archimandrite led the morning prayers at the monastery.","example_pt":"O arquimandrita liderou as orações matinais no mosteiro.","cefr_level":"C2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"archipallium","translation":"arquipálio","definition_en":"The part of the brain's cerebral cortex that is primarily involved in processing smell, also known as the olfactory cortex.","definition_pt":"A parte do córtex cerebral do cérebro que está envolvido principalmente no processamento do cheiro, também conhecido como córtex olfativo.","example_en":"The archipallium is responsible for the initial processing of olfactory signals.","example_pt":"O arquipalium é responsável pelo processamento inicial de sinais olfativos.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"archipelagic","translation":"arquipelágico","definition_en":"Describing something that belongs to, is characteristic of, or is part of a group of islands.","definition_pt":"Descrever algo que pertence, é característico, ou faz parte de um grupo de ilhas.","example_en":"The archipelagic nation of Indonesia consists of thousands of islands.","example_pt":"A nação arquipelágica da Indonésia consiste em milhares de ilhas.","cefr_level":"C1","word_type":"adjective","category_slug":"technical","frequency_rank":null},
{"word":"architectonics","translation":"arquitetônica","definition_en":"The systematic study and theory of architectural design and structure.","definition_pt":"O estudo sistemático e teoria do projeto e estrutura arquitetônica.","example_en":"The professor's lecture on architectonics covered the principles of structural harmony.","example_pt":"A palestra do professor sobre arquitetônica cobria os princípios da harmonia estrutural.","cefr_level":"C2","word_type":"noun","category_slug":"technical","frequency_rank":null},
{"word":"architecturally","translation":"arquiteturalmente","definition_en":"In a way that relates to the design, structure, or style of buildings.","definition_pt":"De uma forma que se relaciona com o projeto, estrutura ou estilo de edifícios.","example_en":"The building is architecturally impressive with its modern facade.","example_pt":"O edifício é arquitetônico impressionante com sua fachada moderna.","cefr_level":"B2","word_type":"adverb","category_slug":"arts","frequency_rank":null},
{"word":"architrave","translation":"arquitrave","definition_en":"The decorative molding or frame that surrounds a door, window, or other opening.","definition_pt":"A moldura decorativa que cerca uma porta, janela ou outra abertura.","example_en":"The craftsman carved intricate patterns into the wooden architrave.","example_pt":"O artesão esculpiu padrões intrincados no arquitrave de madeira.","cefr_level":"C2","word_type":"noun","category_slug":"arts","frequency_rank":null},
{"word":"archival","translation":"arquival","definition_en":"Of or relating to an archive; serving as or contained in a collection of historical records or documents.","definition_pt":"De um arquivo, ou relacionado a ele, servindo como ou contido em uma coleção de registros históricos ou documentos.","example_en":"The museum has an extensive archival collection of photographs.","example_pt":"O museu tem uma extensa coleção de fotografias.","cefr_level":"C2","word_type":"adjective","category_slug":"technical","frequency_rank":null},
{"word":"archly","translation":"maliciosamente","definition_en":"In a way that is teasingly or mischievously sly, often with a hint of irony or superiority.","definition_pt":"De uma forma que é provocante ou travessura, muitas vezes com um toque de ironia ou superioridade.","example_en":"She smiled archly at his comment.","example_pt":"Ela sorriu arqueadamente com o comentário dele.","cefr_level":"C1","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"archosaur","translation":"arcossauro","definition_en":"A group of extinct reptiles that includes dinosaurs, pterosaurs, plesiosaurs, ichthyosaurs, and thecodonts.","definition_pt":"Um grupo de répteis extintos que inclui dinossauros, pterossauros, plesiossauros, ictiossauros e tecodontes.","example_en":"The archosaur group dominated the Mesozoic era.","example_pt":"O grupo dos arcossauros dominava a era Mesozoica.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
{"word":"archway","translation":"arcada","definition_en":"A passage or entrance that is covered by a curved structure, typically made of stone or brick.","definition_pt":"Uma passagem ou entrada que é coberta por uma estrutura curva, tipicamente feita de pedra ou tijolo.","example_en":"They walked through the stone archway into the garden.","example_pt":"Eles caminharam pelo arco de pedra até o jardim.","cefr_level":"B1","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":null},
{"word":"arcsecant","translation":"arco-secante","definition_en":"The inverse function of the secant; the angle whose secant equals a given number.","definition_pt":"A função inversa do secante, o ângulo cujo secante é igual a um determinado número.","example_en":"The arcsecant of 2 is 60 degrees.","example_pt":"O arco-secante de 2 é 60 graus.","cefr_level":"C2","word_type":"noun","category_slug":"science","frequency_rank":null},
